INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > IT-Arbeitsplätze im Kontext > Peripheriegeräte > Externe Speichermedien
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind externe Speichermedien für die Datensicherung an IT-Arbeitsplätzen wichtig?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglichen Backups und Datensicherheit"}, {"text": "Nein", "correct": false, "because": "Datensicherung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Arbeitsplätze ohne externe Speichermedien effizient betrieben werden?', 2, '[{"text": "Ja", "correct": true, "because": "Interne Speicher können ausreichen"}, {"text": "Nein", "correct": false, "because": "Effizienz abhängig von Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind externe Speichermedien immer schneller als interne Speicher?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Technologie ab"}, {"text": "Ja", "correct": false, "because": "Interne oft schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Können externe Speichermedien die Mobilität von Daten an IT-Arbeitsplätzen erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglichen Datentransport"}, {"text": "Nein", "correct": false, "because": "Mobilität wird gesteigert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind externe Speichermedien ausschließlich für die langfristige Datenspeicherung geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für temporäre Nutzung"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktion haben externe Speichermedien an einem IT-Arbeitsplatz?', 3, '[{"text": "Datenspeicherung", "correct": true, "because": "Primäre Aufgabe ist Speichern"}, {"text": "Datenverarbeitung", "correct": false, "because": "Aufgabe der CPU"}, {"text": "Bildausgabe", "correct": false, "because": "Aufgabe des Monitors"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches externe Speichermedium ist für schnelle Datenübertragung bekannt?', 2, '[{"text": "SSD", "correct": true, "because": "Hohe Geschwindigkeit durch Flash-Speicher"}, {"text": "USB-Stick", "correct": false, "because": "Langsamer als SSD"}, {"text": "CD-ROM", "correct": false, "because": "Veraltet und langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl externer Speichermedien entscheidend?', 2, '[{"text": "Kapazität", "correct": true, "because": "Bestimmt Speicherplatz"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Medium wird häufig für Backups an IT-Arbeitsplätzen genutzt?', 3, '[{"text": "Externe Festplatte", "correct": true, "because": "Hohe Kapazität und Zuverlässigkeit"}, {"text": "Floppy-Disk", "correct": false, "because": "Veraltet"}, {"text": "DVD", "correct": false, "because": "Begrenzte Kapazität"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil externer Speichermedien?', 2, '[{"text": "Portabilität", "correct": true, "because": "Einfacher Datentransport"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Nicht Hauptmerkmal"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche externen Speichermedien werden an IT-Arbeitsplätzen genutzt?', 4, '[{"text": "USB-Sticks", "correct": true, "because": "Kompakt und mobil"}, {"text": "Externe Festplatten", "correct": true, "because": "Hohe Kapazität"}, {"text": "SSDs", "correct": true, "because": "Schnell und robust"}, {"text": "Papierstreifen", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten externe Speichermedien?', 3, '[{"text": "Datensicherung", "correct": true, "because": "Schützt vor Datenverlust"}, {"text": "Portabilität", "correct": true, "because": "Einfacher Transport"}, {"text": "Flexibilität", "correct": true, "because": "Vielseitig einsetzbar"}, {"text": "Hohe Verarbeitungsgeschwindigkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl externer Speichermedien?', 3, '[{"text": "Kapazität", "correct": true, "because": "Bestimmt Speicherplatz"}, {"text": "Geschwindigkeit", "correct": true, "because": "Beeinflusst Zugriff"}, {"text": "Robustheit", "correct": true, "because": "Sichert Langlebigkeit"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei externen Speichermedien auftreten?', 4, '[{"text": "Datenverlust", "correct": true, "because": "Bei Defekten möglich"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Mit Geräten"}, {"text": "Langsame Übertragung", "correct": true, "because": "Bei älteren Medien"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen externe Speichermedien nützlich?', 3, '[{"text": "Hohe Kapazität", "correct": true, "because": "Speichert viel Daten"}, {"text": "Mobilität", "correct": true, "because": "Einfach zu transportieren"}, {"text": "Einfache Handhabung", "correct": true, "because": "Benutzerfreundlich"}, {"text": "Hohe Verarbeitungsleistung", "correct": false, "because": "Nicht primär"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Externe Speichermedien unterstützen Datensicherung. b) Sie sind immer schneller als interne Speicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherung ja, Geschwindigkeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SSDs sind schnelle externe Speichermedien. b) IT-Arbeitsplätze benötigen keine externen Speicher.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSDs ja, Speicher nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Externe Festplatten eignen sich für Backups. b) Mobilität ist bei externen Speichermedien unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ja, Mobilität wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kapazität ist ein Kriterium für externe Speichermedien. b) Sie dienen nur der langfristigen Speicherung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kapazität ja, auch temporär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) USB-Sticks erhöhen die Datenmobilität. b) Externe Speichermedien sind unzuverlässig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mobilität ja, Zuverlässigkeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

